"""Auto-generated interceptor verification for Naruto: Shinobi Clash.

Generated by /test-interceptors. Catches the "depths trap": interceptor
wired but effect_fn returns [] silently. For each card with a non-trivial
setup_interceptors function we:

  1. Build a minimal 2-player MTG game state.
  2. Place the card on the battlefield via the same hand -> ZONE_CHANGE
     scaffolding as ``tests/test_naruto.py`` so setup_interceptors
     registers naturally.
  3. Fire the synthetic event the card's interceptor should react to
     (ETB ZONE_CHANGE, OBJECT_DESTROYED, ATTACK_DECLARED, DAMAGE,
     UPKEEP_START, END_STEP, SPELL_CAST).
  4. Assert at least one downstream event was emitted, OR (lord/static
     effects) at least one interceptor with priority != REACT was
     registered. Empty-effect triggers fail the test.

Run via ``PYTHONPATH=. python tests/test_naruto_interceptors.py``.

NOTE: the naruto card set carries the slice-10 ``median-lift`` retrofit
(2026-05-19) and the spice-pass W23 Phase A1 rewires (Tenten, A. Fourth
Raikage, Mei Terumi). This file is the post-retrofit gate — failures
here represent setups that still emit nothing under a minimal harness.
"""

from __future__ import annotations

import importlib.util
import sys
import traceback
from pathlib import Path

REPO_ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(REPO_ROOT))

from src.engine import (  # noqa: E402
    Game, Event, EventType, ZoneType, CardType, Color,
    Characteristics,
)

# Import naruto directly to mirror tests/test_naruto.py (the package
# __init__.py is documented as broken for this set).
_spec = importlib.util.spec_from_file_location(
    "_naruto_under_test",
    str(REPO_ROOT / "src/cards/custom/naruto.py"),
)
_naruto = importlib.util.module_from_spec(_spec)
_spec.loader.exec_module(_naruto)
NARUTO_CARDS = _naruto.NARUTO_CARDS


