# ---------------------------------------------------------------------------
# Scaffolding (mirrors tests/test_naruto.py::create_battlefield_creature)
# ---------------------------------------------------------------------------

def _build_game():
    game = Game()
    p1 = game.add_player("P1")
    p2 = game.add_player("P2")
    return game, p1, p2


def _place_on_battlefield(game, player_id, card_def):
    """Create a card in HAND with no card_def attached, then move it to
    BATTLEFIELD via a synthetic ZONE_CHANGE so setup_interceptors registers
    exactly the way the engine's _handle_zone_change does."""
    obj = game.create_object(
        name=card_def.name,
        owner_id=player_id,
        zone=ZoneType.HAND,
        characteristics=card_def.characteristics,
        card_def=None,
    )
    obj.card_def = card_def
    obj.zone = ZoneType.BATTLEFIELD
    game.emit(Event(
        type=EventType.ZONE_CHANGE,
        payload={
            'object_id': obj.id,
            'from_zone': f'hand_{player_id}',
            'to_zone': 'battlefield',
            'from_zone_type': ZoneType.HAND,
            'to_zone_type': ZoneType.BATTLEFIELD,
        },
        source=obj.id,
        controller=player_id,
    ))
    return obj


def _place_in_graveyard(game, player_id, card_def):
    obj = game.create_object(
        name=card_def.name,
        owner_id=player_id,
        zone=ZoneType.GRAVEYARD,
        characteristics=card_def.characteristics,
        card_def=card_def,
    )
    zone = game.state.zones.get(f"graveyard_{player_id}")
    if zone is not None and obj.id not in zone.objects:
        zone.objects.append(obj.id)
    return obj


def _has_interceptors(obj):
    return len(getattr(obj, "interceptor_ids", []) or []) > 0


def _events_after(game, baseline_len):
    """Slice of the engine event log appended since ``baseline_len``."""
    return game.state.event_log[baseline_len:]


# ---------------------------------------------------------------------------
# Classifier: what kind of trigger does this card carry?
# ---------------------------------------------------------------------------

ETB_PHRASES = (
    "enters the battlefield", "enters,", "when this enters",
    "etb", "you gain", "create a", "scry", "surveil", "draw a card",
    "draws a card", "deals damage to", "deal damage", "discards",
)
DEATH_PHRASES = (
    "dies,", " dies ", "when this dies", "leaves the battlefield",
    "is put into a graveyard", "is destroyed",
)
ATTACK_PHRASES = (
    "whenever this attacks", "attacks,", "this creature attacks",
    "whenever a", "when it attacks",
)
UPKEEP_PHRASES = (
    "at the beginning of your upkeep", "at the beginning of each upkeep",
    "upkeep,",
)
END_STEP_PHRASES = (
    "at the beginning of your end step", "at the beginning of the end step",
    "end step",
)
SPELL_CAST_PHRASES = (
    "whenever you cast", "whenever a player casts", "whenever an opponent casts",
)
DAMAGE_PHRASES = (
    "whenever this deals damage", "whenever this deals combat damage",
    "deals combat damage to a player",
)


def _classify_trigger_kind(text: str) -> set[str]:
    t = text.lower()
    kinds: set[str] = set()
    if any(p in t for p in DEATH_PHRASES):
        kinds.add("death")
    if any(p in t for p in ATTACK_PHRASES):
        kinds.add("attack")
    if any(p in t for p in UPKEEP_PHRASES):
        kinds.add("upkeep")
    if any(p in t for p in END_STEP_PHRASES):
        kinds.add("end_step")
    if any(p in t for p in SPELL_CAST_PHRASES):
        kinds.add("spell_cast")
    if any(p in t for p in DAMAGE_PHRASES):
        kinds.add("combat_damage")
    if any(p in t for p in ETB_PHRASES):
        kinds.add("etb")
    return kinds


# ---------------------------------------------------------------------------
# Per-trigger firing helpers
# ---------------------------------------------------------------------------

def _fire_attack(game, obj):
    obj.state.attacking = True
    return game.emit(Event(
        type=EventType.ATTACK_DECLARED,
        payload={
            'object_id': obj.id,
            'attacker_id': obj.id,
            'controller': obj.controller,
            'attackers': [obj.id],
        },
        source=obj.id,
        controller=obj.controller,
    ))


def _fire_death(game, obj):
    # First move to graveyard via ZONE_CHANGE so the death filter sees the
    # creature in the GY zone (death-trigger default filter resolves the
    # object's current zone), then fire OBJECT_DESTROYED.
    gy = game.state.zones.get(f"graveyard_{obj.controller}")
    bf = game.state.zones.get("battlefield")
    if bf and obj.id in bf.objects:
        bf.objects.remove(obj.id)
    if gy and obj.id not in gy.objects:
        gy.objects.append(obj.id)
    obj.zone = ZoneType.GRAVEYARD
    game.emit(Event(
        type=EventType.ZONE_CHANGE,
        payload={
            'object_id': obj.id,
            'from_zone': 'battlefield',
            'to_zone': f'graveyard_{obj.controller}',
            'from_zone_type': ZoneType.BATTLEFIELD,
            'to_zone_type': ZoneType.GRAVEYARD,
        },
        source=obj.id,
        controller=obj.controller,
    ))
    return game.emit(Event(
        type=EventType.OBJECT_DESTROYED,
        payload={'object_id': obj.id},
        source=obj.id,
        controller=obj.controller,
    ))


def _fire_upkeep(game, obj):
    # make_upkeep_trigger filters on PHASE_START with phase=='upkeep' and
    # checks state.active_player against the source's controller.
    game.state.active_player = obj.controller
    return game.emit(Event(
        type=EventType.PHASE_START,
        payload={'phase': 'upkeep', 'player': obj.controller},
        source=obj.id,
        controller=obj.controller,
    ))


def _fire_end_step(game, obj):
    game.state.active_player = obj.controller
    return game.emit(Event(
        type=EventType.PHASE_START,
        payload={'phase': 'end_step', 'player': obj.controller},
        source=obj.id,
        controller=obj.controller,
    ))


def _fire_spell_cast(game, obj, opp_id):
    # Synthesize an opponent's spell being cast.
    return game.emit(Event(
        type=EventType.SPELL_CAST,
        payload={'controller': opp_id, 'caster': opp_id, 'spell_id': 'phantom'},
        source='phantom',
        controller=opp_id,
    ))


def _fire_combat_damage(game, obj, opp_id):
    return game.emit(Event(
        type=EventType.DAMAGE,
        payload={'source': obj.id, 'target': opp_id, 'amount': 1,
                 'combat': True},
        source=obj.id,
        controller=obj.controller,
    ))


# ---------------------------------------------------------------------------
# Universal per-card test runner
# ---------------------------------------------------------------------------

def _run_card(card_name: str) -> tuple[str, str]:
    """Returns (status, detail). status in {'pass', 'fail', 'skip', 'error'}."""
    if card_name in SKIPPED_CARDS:
        return ("skip", SKIPPED_CARDS[card_name])
    card_def = NARUTO_CARDS[card_name]
    if getattr(card_def, "setup_interceptors", None) is None:
        return ("skip", "no setup_interceptors")
    # Only test cards that go onto the battlefield (creature / artifact /
    # enchantment / land). Instants & sorceries dispatch via cast-effects
    # which need stack scaffolding — out of scope.
    types = (card_def.characteristics.types
             if card_def.characteristics is not None else set())
    if CardType.INSTANT in types or CardType.SORCERY in types:
        return ("skip", "instant/sorcery — cast-effect dispatch")
    if CardType.LAND in types:
        return ("skip", "land — mana-ability dispatch")

    try:
        game, p1, p2 = _build_game()
        baseline = len(game.state.event_log)
        obj = _place_on_battlefield(game, p1.id, card_def)
    except Exception as exc:
        return ("error", f"setup crashed: {type(exc).__name__}: {exc}")

    # Static / lord effects: pass if the card registered any interceptors
    # at all. Their effect surfaces via stat-time queries, not events.
    text = (card_def.text or "").lower()
    kinds = _classify_trigger_kind(text)

    etb_events = _events_after(game, baseline)
    # If the ETB itself emitted downstream events, we're done.
    etb_emitted = any(
        e.type not in (EventType.ZONE_CHANGE, EventType.OBJECT_CREATED)
        for e in etb_events
    )

    if etb_emitted and "etb" in kinds:
        return ("pass", "ETB emitted downstream events")

    # Fire each trigger kind in turn. If any one of them emits a new
    # downstream event we count the card as wired.
    def _try(kind: str, firer) -> tuple[bool, str]:
        before = len(game.state.event_log)
        try:
            firer()
        except Exception as exc:
            return (False, f"{kind} crashed: {type(exc).__name__}: {exc}")
        after = _events_after(game, before)
        if any(e.type not in (EventType.ZONE_CHANGE, EventType.OBJECT_CREATED)
               for e in after):
            return (True, f"{kind} fired ({len(after)} new events)")
        return (False, f"{kind} produced no events")

    attempts: list[str] = []

    if "attack" in kinds:
        ok, why = _try("attack", lambda: _fire_attack(game, obj))
        if ok: return ("pass", why)
        attempts.append(why)

    if "upkeep" in kinds:
        ok, why = _try("upkeep", lambda: _fire_upkeep(game, obj))
        if ok: return ("pass", why)
        attempts.append(why)

    if "end_step" in kinds:
        ok, why = _try("end_step", lambda: _fire_end_step(game, obj))
        if ok: return ("pass", why)
        attempts.append(why)

    if "spell_cast" in kinds:
        ok, why = _try("spell_cast", lambda: _fire_spell_cast(game, obj, p2.id))
        if ok: return ("pass", why)
        attempts.append(why)

    if "combat_damage" in kinds:
        ok, why = _try("combat_damage",
                       lambda: _fire_combat_damage(game, obj, p2.id))
        if ok: return ("pass", why)
        attempts.append(why)

    if "death" in kinds:
        ok, why = _try("death", lambda: _fire_death(game, obj))
        if ok: return ("pass", why)
        attempts.append(why)

    # No explicit kinds matched but interceptors registered -> static/lord.
    # Treat as a soft pass.
    if not kinds:
        if _has_interceptors(obj):
            return ("pass", "static/lord effect — interceptors registered")
        return ("fail", "no interceptors registered, no trigger kind detected")

    # ETB-claimed but emitted nothing AND no other trigger fires.
    if "etb" in kinds and not attempts:
        if _has_interceptors(obj):
            return ("pass", "ETB interceptor registered (possibly state-only effect)")
        return ("fail", "ETB trigger claimed but no interceptor / no events")

    return ("fail", "; ".join(attempts) or "no events emitted")


# ---------------------------------------------------------------------------
# Test entry points - one per card
# ---------------------------------------------------------------------------

def _make_test(card_name: str):
    def _t():
        status, detail = _run_card(card_name)
        if status == "skip":
            # Skipped cards are tracked but don't raise — pytest treats them
            # the same as the standalone runner.
            return
        if status == "pass":
            return
        raise AssertionError(f"[{status}] {card_name}: {detail}")
    _t.__name__ = "test_" + (
        card_name.lower()
        .replace(",", "")
        .replace("'", "")
        .replace(":", "")
        .replace(".", "")
        .replace("-", "_")
        .replace(" ", "_")
    )
    _t.__doc__ = f"{card_name}: auto-generated interceptor verification."
    return _t


# Generate one callable per card eligible for testing (creature / artifact /
# enchantment / land / equipment with setup_interceptors). Instants/sorceries
# and explicit SKIPPED_CARDS are skipped inside _run_card.
_GENERATED: dict[str, callable] = {}
for _name, _cdef in NARUTO_CARDS.items():
    if _cdef is None or getattr(_cdef, "setup_interceptors", None) is None:
        continue
    _types = (_cdef.characteristics.types
              if _cdef.characteristics is not None else set())
    if CardType.INSTANT in _types or CardType.SORCERY in _types:
        continue
    if CardType.LAND in _types:
        continue
    _fn = _make_test(_name)
    _GENERATED[_fn.__name__] = _fn
    globals()[_fn.__name__] = _fn


# ---------------------------------------------------------------------------
# Standalone runner
# ---------------------------------------------------------------------------

if __name__ == "__main__":
    passed: list[str] = []
    failed: list[tuple[str, str]] = []
    errors: list[tuple[str, str]] = []
    skipped: list[tuple[str, str]] = []

    eligible = sorted(NARUTO_CARDS.keys())
    for card_name in eligible:
        cdef = NARUTO_CARDS[card_name]
        if cdef is None or getattr(cdef, "setup_interceptors", None) is None:
            continue
        types = (cdef.characteristics.types
                 if cdef.characteristics is not None else set())
        if CardType.INSTANT in types or CardType.SORCERY in types:
            skipped.append((card_name, "instant/sorcery — cast-effect dispatch"))
            continue
        if CardType.LAND in types:
            skipped.append((card_name, "land — mana-ability dispatch"))
            continue
        if card_name in SKIPPED_CARDS:
            skipped.append((card_name, SKIPPED_CARDS[card_name]))
            continue
        try:
            status, detail = _run_card(card_name)
        except Exception as exc:
            errors.append((card_name, f"{type(exc).__name__}: {exc}"))
            continue
        if status == "pass":
            passed.append(card_name)
        elif status == "fail":
            failed.append((card_name, detail))
        elif status == "error":
            errors.append((card_name, detail))
        else:
            skipped.append((card_name, detail))

    total_run = len(passed) + len(failed) + len(errors)
    print("\n=== Interceptor verification: naruto ===")
    print(f"  cards in pool:      {len(NARUTO_CARDS)}")
    print(f"  tests run:          {total_run}")
    print(f"  passed:             {len(passed)}")
    print(f"  failed:             {len(failed)}")
    print(f"  errors:             {len(errors)}")
    print(f"  skipped:            {len(skipped)}")
    rate = (100.0 * len(passed) / total_run) if total_run else 0.0
    print(f"  pass rate:          {rate:.1f}%")

    if failed:
        print("\n--- FAILURES (first 30) ---")
        for name, msg in failed[:30]:
            print(f"  FAIL {name}: {msg}")
    if errors:
        print("\n--- ERRORS (first 30) ---")
        for name, msg in errors[:30]:
            print(f"  ERR  {name}: {msg}")
    if skipped:
        print(f"\n--- SKIPPED ({len(skipped)} cards, first 15) ---")
        for name, msg in skipped[:15]:
            print(f"  skip {name}: {msg}")

    sys.exit(0 if not failed and not errors else 1)
